namespace Demo;
class Box { public int N; }
static class State {
 public static int Count;
 public static long Long = 4L;
 public static readonly string Name;
 public static string Label { get; } = "ready";
 public static int Value { get; private set; }
 public static Box Box = new Box { N = 2 };
 static State() { Name = "Ada"; Label = "done"; Value = 3; }
 public static int Add(int n) { Count += n; Value++; return Value; }
}
void Main() {
 Print(State.Count); Print(State.Name + ":" + State.Label); Print(State.Add(2));
 Print(State.Count++); Print(++State.Count); Print(State.Long += 2);
 State.Box.N++; Print(State.Box.N); Print(State.Value);
}
